import { Router } from "express";
import { authMiddleware } from "../../middlewares/auth.middleware.js";
import { requireOnboarding } from "../../middlewares/onboarding.middleware.js";
import { portalRoleMiddleware } from "../../middlewares/role.middleware.js";
import { upload } from "../../middlewares/upload.middleware.js";
import { uploadFile } from "../../controllers/media/media.controller.js";
import { getMyVerification, updateMyVerification, deleteMyVerification } from "../../controllers/verification/verification.controller.js";
import { getFounderDashboard, getFounderProfile, updateFounderProfile, getFounderStartup, updateFounderStartup, getBusinessPlan, putBusinessPlan, getPitchDeck, putPitchDeck, getFounderFunding, listInvestorRequests, respondInvestorRequest, listFounderInvestors, listAllInvestors, listFounderTeam, addFounderTeamMember, deleteFounderTeamMember, listFounderDocuments, addFounderDocument, listFounderMilestones, addFounderMilestone, updateFounderMilestone, deleteFounderMilestone, listFounderMeetings, createFounderMeeting, listFounderMessages, createFounderMessage, getFounderWallet, depositFounderWallet, withdrawFounderWallet, listFounderInvoices, getFounderAnalytics, getFounderReports, listFounderNotifications, markFounderNotificationRead, markAllFounderNotificationsRead, listFounderSubscriptions, purchaseFounderSubscription, getFounderSettings, updateFounderSettings, listFounderRoles, listFounderReviews, } from "../../controllers/founder/founder.controller.js";
import { listWatchlist, addToWatchlist, removeFromWatchlist, } from "../../controllers/investor/investor.controller.js";
const router = Router();
router.use(authMiddleware);
// Portal media upload is needed DURING onboarding for avatars and documents
router.post("/media/upload", upload.single("file"), uploadFile);
// Verification routes must be accessible before onboarding completion so users can upload KYC documents
router.get("/verification", getMyVerification);
router.patch("/verification", updateMyVerification);
router.delete("/verification", deleteMyVerification);
router.use(requireOnboarding);
router.use(portalRoleMiddleware(["founder", "investor", "client", "freelancer", "admin", "super_admin"]));
// Watchlist routes
router.get("/watchlist", listWatchlist);
router.post("/watchlist", addToWatchlist);
router.delete("/watchlist/:id", removeFromWatchlist);
router.get("/dashboard", getFounderDashboard);
router.get("/profile", getFounderProfile);
router.patch("/profile", updateFounderProfile);
router.put("/profile", updateFounderProfile);
router.get("/startup", getFounderStartup);
router.patch("/startup", updateFounderStartup);
router.put("/startup", updateFounderStartup);
router.post("/startup/logo", upload.single("file"), uploadFile);
router.get("/business-plan", getBusinessPlan);
router.put("/business-plan", putBusinessPlan);
router.get("/pitch-deck", getPitchDeck);
router.put("/pitch-deck", putPitchDeck);
router.get("/funding", getFounderFunding);
router.get("/investor-requests", listInvestorRequests);
router.post("/investor-requests/:id/respond", respondInvestorRequest);
router.get("/investors", listFounderInvestors);
router.get("/all-investors", listAllInvestors);
router.get("/team", listFounderTeam);
router.post("/team", addFounderTeamMember);
router.delete("/team/:id", deleteFounderTeamMember);
router.get("/roles", listFounderRoles);
router.get("/documents", listFounderDocuments);
router.post("/documents", addFounderDocument);
router.get("/milestones", listFounderMilestones);
router.post("/milestones", addFounderMilestone);
router.patch("/milestones/:id", updateFounderMilestone);
router.delete("/milestones/:id", deleteFounderMilestone);
router.get("/meetings", listFounderMeetings);
router.post("/meetings", createFounderMeeting);
router.get("/messages", listFounderMessages);
router.post("/messages", createFounderMessage);
router.get("/wallet", getFounderWallet);
router.post("/wallet/deposit", depositFounderWallet);
router.post("/wallet/withdraw", withdrawFounderWallet);
router.get("/invoices", listFounderInvoices);
router.get("/analytics", getFounderAnalytics);
router.get("/reports", getFounderReports);
router.get("/notifications", listFounderNotifications);
router.patch("/notifications/read-all", markAllFounderNotificationsRead);
router.patch("/notifications/:id/read", markFounderNotificationRead);
router.get("/subscription", listFounderSubscriptions);
router.get("/subscriptions", listFounderSubscriptions);
router.post("/subscription/purchase", purchaseFounderSubscription);
router.post("/subscriptions/purchase", purchaseFounderSubscription);
router.get("/settings", getFounderSettings);
router.patch("/settings", updateFounderSettings);
router.get("/reviews", listFounderReviews);
// Professional Services
import { listFreelancerServices, getFreelancerServiceById, createFreelancerService, updateFreelancerService, deleteFreelancerService, } from "../../controllers/freelancer/freelancer-modules.controller.js";
router.get("/services", listFreelancerServices);
router.get("/profile/services", listFreelancerServices);
router.post("/services", createFreelancerService);
router.post("/profile/services", createFreelancerService);
router.get("/services/:id", getFreelancerServiceById);
router.get("/profile/services/:id", getFreelancerServiceById);
router.put("/services/:id", updateFreelancerService);
router.put("/profile/services/:id", updateFreelancerService);
router.delete("/services/:id", deleteFreelancerService);
router.delete("/profile/services/:id", deleteFreelancerService);
// Languages
import { listFreelancerLanguages, createFreelancerLanguage, updateFreelancerLanguage, deleteFreelancerLanguage, } from "../../controllers/freelancer/freelancer-modules.controller.js";
router.get("/languages", listFreelancerLanguages);
router.get("/profile/languages", listFreelancerLanguages);
router.post("/languages", createFreelancerLanguage);
router.post("/profile/languages", createFreelancerLanguage);
router.put("/languages/:id", updateFreelancerLanguage);
router.put("/profile/languages/:id", updateFreelancerLanguage);
router.delete("/languages/:id", deleteFreelancerLanguage);
router.delete("/profile/languages/:id", deleteFreelancerLanguage);
// Profile Custom FAQs
import { getMyProfileFaqs, saveMyProfileFaqs } from "../../controllers/user-faqs.controller.js";
router.get("/profile/faqs", getMyProfileFaqs);
router.put("/profile/faqs", saveMyProfileFaqs);
router.post("/profile/faqs", saveMyProfileFaqs);
export default router;
